<?php
declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(403);exit('CLI only');}require __DIR__.'/../config/bootstrap.php';require __DIR__.'/../lib/MaketouClient.php';require __DIR__.'/../lib/TopupClient.php';$pdo=db();$rows=$pdo->query("SELECT o.*,p.provider_sku FROM orders o JOIN products p ON p.id=o.product_id WHERE o.payment_status='pending' AND o.maketou_reference IS NOT NULL ORDER BY o.id LIMIT 50")->fetchAll();$m=new MaketouClient((string)config('maketou.api_key'));$t=new TopupClient((string)config('topup.api_key'),(string)config('topup.base_url','https://topup.dev'));foreach($rows as $o){try{$cart=$m->cart($o['maketou_reference']);$status=$cart['status']??'';if($status==='completed'){$pdo->prepare("UPDATE orders SET payment_status='paid' WHERE id=? AND payment_status='pending'")->execute([$o['id']]);$fresh=$pdo->prepare('SELECT delivery_status FROM orders WHERE id=?');$fresh->execute([$o['id']]);$state=$fresh->fetchColumn();if($state==='pending'&&!empty($o['provider_sku'])){$data=json_decode($o['customer_data'],true)?:[];$player=$data['player']??['uid'=>$data['identifier']??''];$callback=rtrim(config('app.base_url'),'/').'/webhooks/topup.php';$res=$t->create($o['provider_sku'],$player,$callback,$o['order_number']);$providerId=$res['id']??$res['order_id']??null;$pdo->prepare("UPDATE orders SET delivery_status='processing',provider_order_id=?,provider_response=? WHERE id=?")->execute([$providerId,json_encode($res,JSON_UNESCAPED_UNICODE),$o['id']]);}}elseif(in_array($status,['payment_failed','abandoned'],true)){$pdo->prepare("UPDATE orders SET payment_status=? WHERE id=?")->execute([$status==='abandoned'?'cancelled':'failed',$o['id']]);}}catch(Throwable $e){$pdo->prepare('INSERT INTO order_events(order_id,event_type,status,message) VALUES(?,?,?,?)')->execute([$o['id'],'reconcile_error','error',$e->getMessage()]);}}
echo "done\n";
